#!/usr/bin/env python3
"""Measure how boundary transport changes the unique negative TP2 witness."""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'research/benincasa/.tmp_sympy'));import sympy as s
src=json.loads((ROOT/'research/nima/results/nnmhv-kernel-wall-tail-boundary.json').read_text());K=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_matrix']]);K0=s.Matrix([[s.sympify(x) for x in row] for row in src['kernel_without_upper_boundary_transport']]);I=(1,2);J=(0,1);d=s.factor(K.extract(I,J).det());d0=s.factor(K0.extract(I,J).det());odds=s.factor(K[1,0]*K[2,1]/(K[1,1]*K[2,0]));odds0=s.factor(K0[1,0]*K0[2,1]/(K0[1,1]*K0[2,0]));logsign=lambda q:-1 if q<1 else 1 if q>1 else 0;all2=lambda A:[s.factor(A.extract(I,J).det()) for I in __import__('itertools').combinations(range(A.rows),2) for J in __import__('itertools').combinations(range(A.cols),2)];checks={'updated_minor_negative':s.sign(d)==-1,'unupdated_minor_positive':s.sign(d0)==1,'updated_odds_ratio_below_one':odds<1,'unupdated_odds_ratio_above_one':odds0>1,'boundary_update_flips_witness_sign':s.sign(d)!=s.sign(d0),'negative_minor_created_uniquely':sum(bool(s.sign(x)<0) for x in all2(K))==1 and sum(bool(s.sign(x)<0) for x in all2(K0))==0};checks={k:bool(v) for k,v in checks.items()}
out={'schema':'marici.nima.nnmhv-boundary-update-interference-minor.v1','minor':'rows (b1=6,7), columns (b2=5,6)','with_boundary_update':{'determinant':str(d),'odds_ratio':str(odds),'odds_ratio_numeric':float(odds)},'without_upper_boundary_transport':{'determinant':str(d0),'odds_ratio':str(odds0),'odds_ratio_numeric':float(odds0)},'checks':checks,'passed':all(checks.values()),'meaning':'The transported upper-boundary replacement creates the unique negative TP2/association witness: it flips an initially positive higher minor and changes the local odds ratio from above one to far below one.','bridges':['negative association odds ratio','TP2/log-supermodularity witness','two-by-two interference determinant','oriented-matroid sign data','boundary renormalization of bulk coherence']};p=ROOT/'research/nima/results/nnmhv-boundary-update-interference-minor.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
